#include <iostream>
#include <vector>
#include <cstring>
#include <cmath>
#include <cstdio>
using namespace std;

const long long INF = 1e18;
long long n, k;
vector<long long> vec;

long long solve(){
    vector<long long> dp(n, INF);
    dp[n - 1] = 0;
    for(long long index = n - 2; index >= 0; index--){
        for(long long i = 1; i <= k; i++){
 if(index + i < n){
     dp[index] = min(dp[index], abs(vec[index] - vec[index + i]) + dp[index + i]);
 }
        }
    }
    return dp[0];
}

int main(){
    scanf("%lld %lld", &n, &k);
    vec.resize(n);
    for(long long i = 0; i < n; i++){
        scanf("%lld", &vec[i]);
    }
    printf("%lld\n", solve());
    return 0;
}

